-- Native vSRO skill reference catalog. Data is explicitly copied from the
-- restored SRO_VT_SHARD reference database by `sro-data import-vsro-skills`.
CREATE TABLE `REF_SKILL_GROUP` (`ID` INT NOT NULL, `CODE` VARCHAR(128) NOT NULL, PRIMARY KEY (`ID`)) ENGINE=InnoDB;
CREATE TABLE `REF_SKILL_MASTERY` (`ID` INT NOT NULL, `CODE` VARCHAR(32) NOT NULL, `WEAPON` TINYINT NOT NULL, PRIMARY KEY (`ID`)) ENGINE=InnoDB;

CREATE TABLE `REF_SKILL` (
 `SERVICE` TINYINT NOT NULL, `ID` INT NOT NULL, `GROUP_ID` INT NOT NULL,
 `BASIC_CODE` VARCHAR(128) NOT NULL, `BASIC_NAME` VARCHAR(128) NOT NULL, `BASIC_GROUP` VARCHAR(128) NOT NULL, `BASIC_ORIGINAL` INT NOT NULL, `BASIC_LEVEL` TINYINT NOT NULL, `BASIC_ACTIVITY` TINYINT NOT NULL, `BASIC_CHAINCODE` INT NOT NULL, `BASIC_RECYCLECOST` INT NOT NULL,
 `ACTION_PREPARINGTIME` INT NOT NULL, `ACTION_CASTINGTIME` INT NOT NULL, `ACTION_ACTIONDURATION` INT NOT NULL, `ACTION_REUSEDELAY` INT NOT NULL, `ACTION_COOLTIME` INT NOT NULL, `ACTION_FLYINGSPEED` INT NOT NULL, `ACTION_INTERRUPTIBLE` TINYINT NOT NULL, `ACTION_OVERLAP` INT NOT NULL, `ACTION_AUTOATTACKTYPE` TINYINT NOT NULL, `ACTION_INTOWN` TINYINT NOT NULL, `ACTION_RANGE` SMALLINT NOT NULL,
 `TARGET_REQUIRED` TINYINT NOT NULL, `TARGETTYPE_ANIMAL` TINYINT NOT NULL, `TARGETTYPE_LAND` TINYINT NOT NULL, `TARGETTYPE_BUILDING` TINYINT NOT NULL, `TARGETGROUP_SELF` TINYINT NOT NULL, `TARGETGROUP_ALLY` TINYINT NOT NULL, `TARGETGROUP_PARTY` TINYINT NOT NULL, `TARGETGROUP_ENEMY_M` TINYINT NOT NULL, `TARGETGROUP_ENEMY_P` TINYINT NOT NULL, `TARGETGROUP_NEUTRAL` TINYINT NOT NULL, `TARGETGROUP_DONTCARE` TINYINT NOT NULL, `TARGETETC_SELECTDEADBODY` TINYINT NOT NULL,
 `REQCOMMON_MASTERY1` INT NOT NULL, `REQCOMMON_MASTERY2` INT NOT NULL, `REQCOMMON_MASTERYLEVEL1` TINYINT NOT NULL, `REQCOMMON_MASTERYLEVEL2` TINYINT NOT NULL, `REQCOMMON_STR` SMALLINT NOT NULL, `REQCOMMON_INT` SMALLINT NOT NULL, `REQLEARN_SKILL1` INT NOT NULL, `REQLEARN_SKILL2` INT NOT NULL, `REQLEARN_SKILL3` INT NOT NULL, `REQLEARN_SKILLLEVEL1` TINYINT NOT NULL, `REQLEARN_SKILLLEVEL2` TINYINT NOT NULL, `REQLEARN_SKILLLEVEL3` TINYINT NOT NULL, `REQLEARN_SP` INT NOT NULL, `REQLEARN_RACE` TINYINT NOT NULL, `REQ_RESTRICTION1` TINYINT NOT NULL, `REQ_RESTRICTION2` TINYINT NOT NULL, `REQCAST_WEAPON1` TINYINT NOT NULL, `REQCAST_WEAPON2` TINYINT NOT NULL,
 `CONSUME_HP` SMALLINT NOT NULL, `CONSUME_MP` SMALLINT NOT NULL, `CONSUME_HPRATIO` SMALLINT NOT NULL, `CONSUME_MPRATIO` SMALLINT NOT NULL, `CONSUME_WHAN` TINYINT NOT NULL, `UI_SKILLTAB` TINYINT NOT NULL, `UI_SKILLPAGE` TINYINT NOT NULL, `UI_SKILLCOLUMN` TINYINT NOT NULL, `UI_SKILLROW` TINYINT NOT NULL, `UI_ICONFILE` VARCHAR(128) NOT NULL, `UI_SKILLNAME` VARCHAR(128) NOT NULL, `UI_SKILLTOOLTIP` VARCHAR(128) NOT NULL, `UI_SKILLTOOLTIP_DESC` VARCHAR(128) NOT NULL, `UI_SKILLSTUDY_DESC` VARCHAR(128) NOT NULL, `AI_ATTACKCHANCE` SMALLINT NOT NULL, `AI_SKILLTYPE` TINYINT NOT NULL,
 `PARAM1` INT NULL, `PARAM2` INT NULL, `PARAM3` INT NULL, `PARAM4` INT NULL, `PARAM5` INT NULL, `PARAM6` INT NULL, `PARAM7` INT NULL, `PARAM8` INT NULL, `PARAM9` INT NULL, `PARAM10` INT NULL, `PARAM11` INT NULL, `PARAM12` INT NULL, `PARAM13` INT NULL, `PARAM14` INT NULL, `PARAM15` INT NULL, `PARAM16` INT NULL, `PARAM17` INT NULL, `PARAM18` INT NULL, `PARAM19` INT NULL, `PARAM20` INT NULL, `PARAM21` INT NULL, `PARAM22` INT NULL, `PARAM23` INT NULL, `PARAM24` INT NULL, `PARAM25` INT NULL, `PARAM26` INT NULL, `PARAM27` INT NULL, `PARAM28` INT NULL, `PARAM29` INT NULL, `PARAM30` INT NULL, `PARAM31` INT NULL, `PARAM32` INT NULL, `PARAM33` INT NULL, `PARAM34` INT NULL, `PARAM35` INT NULL, `PARAM36` INT NULL, `PARAM37` INT NULL, `PARAM38` INT NULL, `PARAM39` INT NULL, `PARAM40` INT NULL, `PARAM41` INT NULL, `PARAM42` INT NULL, `PARAM43` INT NULL, `PARAM44` INT NULL, `PARAM45` INT NULL, `PARAM46` INT NULL, `PARAM47` INT NULL, `PARAM48` INT NULL, `PARAM49` INT NULL, `PARAM50` INT NULL,
 PRIMARY KEY (`ID`), KEY `idx_ref_skill_group` (`GROUP_ID`), KEY `idx_ref_skill_mastery_1` (`REQCOMMON_MASTERY1`), KEY `idx_ref_skill_mastery_2` (`REQCOMMON_MASTERY2`),
 CONSTRAINT `fk_ref_skill_group` FOREIGN KEY (`GROUP_ID`) REFERENCES `REF_SKILL_GROUP` (`ID`)
) ENGINE=InnoDB;

CREATE TABLE `REF_SKILL_BY_ITEM_OPT_LEVEL` (`LINK` INT NOT NULL, `REF_SKILL_ID` INT NOT NULL, PRIMARY KEY (`LINK`), CONSTRAINT `fk_ref_skill_opt_level_skill` FOREIGN KEY (`REF_SKILL_ID`) REFERENCES `REF_SKILL` (`ID`)) ENGINE=InnoDB;
CREATE TABLE `REF_CHAR_DEFAULT_SKILL_VSRO` (`RACE` TINYINT NOT NULL, `SKILL_ID` INT NOT NULL, PRIMARY KEY (`RACE`,`SKILL_ID`), CONSTRAINT `fk_ref_char_default_skill_vsro` FOREIGN KEY (`SKILL_ID`) REFERENCES `REF_SKILL` (`ID`)) ENGINE=InnoDB;
CREATE TABLE `REF_CHAR_DEFAULT_SKILL_MASTERY_VSRO` (`RACE` TINYINT NOT NULL, `MASTERY_ID` INT NOT NULL, PRIMARY KEY (`RACE`,`MASTERY_ID`), CONSTRAINT `fk_ref_char_default_skill_mastery_vsro` FOREIGN KEY (`MASTERY_ID`) REFERENCES `REF_SKILL_MASTERY` (`ID`)) ENGINE=InnoDB;
CREATE TABLE `REF_OBJ_CHAR_EXTRA_SKILL` (`ID` INT NOT NULL, `CHAR_ID` INT NOT NULL, `EXTRA_SKILL_1` INT NULL, `EXTRA_SKILL_2` INT NULL, `EXTRA_SKILL_3` INT NULL, `EXTRA_SKILL_4` INT NULL, `EXTRA_SKILL_5` INT NULL, `EXTRA_SKILL_6` INT NULL, `EXTRA_SKILL_7` INT NULL, `EXTRA_SKILL_8` INT NULL, `EXTRA_SKILL_9` INT NULL, `EXTRA_SKILL_10` INT NULL, `EXTRA_SKILL_11` INT NULL, `EXTRA_SKILL_12` INT NULL, `EXTRA_SKILL_13` INT NULL, `EXTRA_SKILL_14` INT NULL, `EXTRA_SKILL_15` INT NULL, `EXTRA_SKILL_16` INT NULL, `EXTRA_SKILL_17` INT NULL, `EXTRA_SKILL_18` INT NULL, `EXTRA_SKILL_19` INT NULL, `EXTRA_SKILL_20` INT NULL, PRIMARY KEY (`ID`)) ENGINE=InnoDB;
